void UsbCodeUpdater::processEvent( Util::CSmartPtr< EvolMessageWrapper> & msg )
{

	if ( msg.get() != NULL )
	{
		switch (msg->getDeviceType())
		{
			case VersionManagerDev:
				handleVersionManagerDevEvent((VersionManagerEvent) msg->getEventType(), msg->Data());
				break;
			default:
				break;
		}
	}
}

void UsbCodeUpdater::handleVersionManagerDevEvent(VersionManagerEvent verManagerEvent, const char *recvBuffer)
{
	switch (verManagerEvent)
	{
		case PeripheralUpdateCode:
			{
				PeripheralCodeUpdate codeUpdate(recvBuffer);
				codeUpdate.show();

				if (codeUpdate.getNodeId() == pIPeripheralUpdater->getUsbNodeId())
				{
					switch (codeUpdate.getVersionType())
					{
						case HobVersion::UsbWeigher15KgSW:
							{
								HobString codeLocation = "";
								util_filesystem::Directory *srcDir = codeUpdate.getPath();
								util_filesystem::File weigherHex(srcDir->getFullPath(), "weigher.hex");

								if ((weigherHex.exists() == true) && (codeUpdate.getResponseType() == SoftwareSystem::AvailableUpgrade))
								{
									Debug::trace("UsbCodeUpdater", HobString("processing tar path=") + HobString(weigherHex.getFullPath().c_str()));
									codeLocation = HobString(weigherHex.getFullPath().c_str());

									VmStatusMsg status(NULL, VersionManagerUsbWeigherDownloading, HfcResponse::RESPONSESTYLE_NOINPUT, false);
									dispatchEvent(&status);

									pIPeripheralUpdater->createCommLink();
									pIPeripheralUpdater->initializePeripheral();
									pIPeripheralUpdater->downloadCode(codeLocation.c_str());
									pIPeripheralUpdater->finalizePeripheral();
									pIPeripheralUpdater->rebootPeripheral();
									pIPeripheralUpdater->deleteCommLink();

									status.setStatusCode(VersionManagerUsbWeigherDownloading);
									status.setResponseType(HfcResponse::RESPONSESTYLE_NOINPUT);
									status.setRemoveDialog(true);
									dispatchEvent(&status);
/*
									status.setStatusCode(VersionManagerUsbWeigherDownloadSucceeded);
									status.setResponseType(HfcResponse::RESPONSESTYLE_OK);
									status.setRemoveDialog(false);
									dispatchEvent(&status, this);
*/
									cleanUpWorkspace(srcDir);

								}
								else
								{
									VmStatusMsg status(NULL, VersionManagerUsbWeigherDownloadFailed, HfcResponse::RESPONSESTYLE_OK, false);
									dispatchEvent(&status);
								}

								updateComplete = true;
							}
							break;
						default:
							break;
					}
				}
			}
			break;
		default:
			break;
	}
}

void UsbCodeUpdater::cleanUpWorkspace(util_filesystem::Directory *pDir)
{
	pDir->remove(true);
}

bool UsbCodeUpdater::isUpdateComplete()
{
	return updateComplete;
}
